    const [ing, base, subj, tb, es] = rng.pick(actions);
    return [
      hu(`${subj} ${tb} ___ right now. (${es})`, '', 'Forma -ing tras To Be:', ing, [ing, base, `${base}s`, `${base}ed`], ing, `${tb} + ${ing} = acción en progreso ahora mismo.`),
      op('¿Qué significa «They are being very kind today»?', 'being', 'Están siendo muy amables hoy', ['Están siendo muy amables hoy', 'Eran muy amables antes', 'Trabajan todo el día', 'Siempre fueron así'], 'Están siendo muy amables hoy', 'Are + being expresa una actitud temporal en este momento.')
    ];
